// Build interactive WhatsApp Category List Picker with active Herbs & Spices, Deals & Bundles, and Bid Boxes & Favors
const categories = [
  {
    id: 'cat_nuts',
    title: 'Dry Fruits & Nuts',
    description: 'Almonds, Pistachios, Cashews, Walnuts, Chilgoza & Dates'
  },
  {
    id: 'cat_bid_boxes',
    title: 'Bid Boxes & Favors',
    description: 'Empty & Filled Nikkah, Umrah Tabarruk & Celebration Boxes'
  },
  {
    id: 'cat_bundles',
    title: 'Deals & Bundles',
    description: '1kg Combo Duos, Daily Wellness Packs & Luxury Gift Hampers'
  },
  {
    id: 'cat_herbs_spices',
    title: 'Herbs & Spices',
    description: 'Cardamom, Cinnamon, Cloves, Zafran, Gond & Artisanal Masalas'
  },
  {
    id: 'cat_oils',
    title: 'Cold-Pressed Oils',
    description: 'Pure Almond, Black Seed, Olive, Walnut & Chilgoza Oils'
  },
  {
    id: 'cat_essentials',
    title: 'Desi Essentials',
    description: 'Pure Desi Ghee, Wild Honey, Traditional Panjeeri & Shakkar'
  },
  {
    id: 'cat_snacks_seeds',
    title: 'Snacks & Super Seeds',
    description: 'Chia, Pumpkin, Flax, Makhana, Lahori Nimko & Roasted Chanay'
  },
  {
    id: 'cat_custom_quote',
    title: 'Custom Quote / Bargain',
    description: 'Pitch your target budget for 25–500+ Shadi / Event Boxes'
  }
];

return [{
  json: {
    interactiveType: 'list',
    headerText: 'AllBarka Luxury Boutique',
    bodyText: 'Assalam-o-Alaikum! Select a category below to browse live prices, order Empty or Filled Bid Boxes, or request a Custom Bargain Quote:',
    buttonText: 'Browse Categories',
    sections: [{
      title: 'AllBarka Live Catalog',
      rows: categories
    }]
  }
}];

// Authoritative WhatsApp Order Price Calculator supporting weight (g/kg), bottle (ml), and piece (Bid Boxes, Deals & Bundles)
const input = $input.first().json || {};
const product = input.product || {};
const unit = String(product.unit || 'weight').toLowerCase();
const quantity = Math.max(1, Number(input.quantity || 1));
const weightG = Number(product.weight_g || 250);
const basePrice = Number(product.price || 0);
const city = String(input.city || 'Lahore').trim();
const isLahore = /^lahore$/i.test(city);

// Route Custom Quote / Bargain or quote-only items to Human Concierge
if (input.isBargainRequest || input.targetPricePkr || basePrice <= 0 || product.category === 'custom-quote') {
  return [{
    json: {
      ok: true,
      routeTo: 'CUSTOM_ORDER_HANDOFF',
      reason: 'CUSTOM_QUOTE_OR_BARGAIN',
      productId: product.product_id || product.base_product_id || 'custom',
      productName: product.name || 'Custom Bid Box / Event Package',
      mode: input.mode || 'filled',
      quantity,
      targetPricePkr: input.targetPricePkr || null,
      city,
      handoffPhone: '923160666083'
    }
  }];
}

let unitPrice = basePrice;
let totalWeightG = weightG * quantity;
let bulkDiscountApplied = null;

if (unit === 'piece') {
  // Piece-based items (Bid Boxes, Gift Boxes, Deals & Bundles) bypass the loose 250g minimum check
  // Apply automatic bulk tier discounts when ordering single Empty Bid Boxes in bulk quantities
  const pid = String(product.product_id || '');
  if (pid.startsWith('bid-box-') && pid.includes('empty-box-1-pc')) {
    if (quantity >= 100 && product.wholesale_per_kg > 0) {
      unitPrice = Number(product.wholesale_per_kg);
      bulkDiscountApplied = '100+ pcs (-18% Bulk Rate)';
    } else if (quantity >= 50) {
      unitPrice = Math.round(basePrice * 0.9);
      bulkDiscountApplied = '50+ pcs (-10% Bulk Rate)';
    } else if (quantity >= 25) {
      unitPrice = Math.round(basePrice * 0.95);
      bulkDiscountApplied = '25+ pcs (-5% Bulk Rate)';
    }
  }
} else if (unit === 'bottle') {
  // Cold-pressed oils billed by canonical bottle size
  unitPrice = basePrice;
} else {
  // Loose weight items: allow 100g+ for spices/seeds/saffron, 250g+ for standard nuts
  const minAllowedG = ['herbs-spices', 'snacks-seeds', 'essentials'].includes(product.category) ? 100 : 250;
  if (weightG < minAllowedG && !product.product_id?.includes('100g') && !product.product_id?.includes('g')) {
    return [{
      json: {
        ok: false,
        error: `Minimum order weight for ${product.name} is ${minAllowedG}g.`,
        code: 'MIN_WEIGHT_REQUIRED'
      }
    }];
  }
}

const subtotal = Math.round(unitPrice * quantity);
const shipping = isLahore
  ? (subtotal >= 5000 ? 0 : 250)
  : Math.max(350, Math.ceil((totalWeightG / 1000) * 250));
const total = subtotal + shipping;

return [{
  json: {
    ok: true,
    routeTo: 'STANDARD_CHECKOUT',
    productId: product.product_id,
    baseProductId: product.base_product_id,
    productName: product.name,
    unit,
    quantity,
    unitPrice,
    bulkDiscountApplied,
    subtotal,
    shipping,
    total,
    totalWeightG,
    city
  }
}];

const data = $input.first().json || {};
if (data.routeTo === 'CUSTOM_ORDER_HANDOFF') {
  return [{
    json: {
      ...data,
      action: 'HUMAN_CONCIERGE_HANDOFF',
      replyText: `JazakAllah! Your custom quote / bargain inquiry for *${data.productName}* (Qty: ${data.quantity}) has been forwarded to our Senior Event & Wholesale Desk (+92 316 0666083). Our team will pitch our best custom rate shortly.`
    }
  }];
}
return [{ json: data }];
